# -*- coding: utf-8 -*-
# 18 more proofs (Jurgensen-level plus Honors extensions). Each step is (statement, reason).
PR2=[
dict(id='p-conv-alt',t='par',title='Alternate interior angles equal means the lines are parallel',
 given='Lines ℓ and m are cut by transversal t. Alternate interior angles ∠1 and ∠2 are congruent. ∠3 is the vertical angle of ∠2.',prove='ℓ ∥ m',
 steps=[('∠1 ≅ ∠2','Given'),('∠2 ≅ ∠3','Vertical angles are congruent'),('∠1 ≅ ∠3','Transitive property of congruence'),('ℓ ∥ m','If corresponding angles are congruent, the lines are parallel')],
 idea='Turn the angle pair you have into the pair a postulate talks about (corresponding angles).',
 deep='This is the converse of the alternate interior angles theorem. The Corresponding Angles Postulate is accepted without proof; every other parallel-line test is built from it plus vertical angles.',
 trap='Do not use “alternate interior angles are congruent” as a reason when you are trying to prove lines parallel. That is the theorem for parallel lines, not the test.'),
dict(id='p-conv-iso',t='tri',title='If two angles of a triangle are equal, the sides opposite them are equal',
 given='△ABC with ∠B ≅ ∠C. Draw the bisector of ∠A meeting BC at D.',prove='AB = AC',
 steps=[('∠BAD ≅ ∠CAD','Definition of angle bisector'),('∠B ≅ ∠C','Given'),('AD = AD','Reflexive property'),('△ABD ≅ △ACD','AAS'),('AB = AC','CPCTC')],
 idea='Build two triangles that share a side, prove them congruent, then read off the equal sides.',
 deep='This is the converse of the isosceles triangle theorem. Notice the bisector gives the “extra” angle pair needed for AAS; a perpendicular from A would also work.',
 trap='You need the shared side AD as the non-included side for AAS. The angle at D is not given, so SAS would be wrong.'),
dict(id='p-rhom',t='quad',title='The diagonals of a rhombus are perpendicular',
 given='Rhombus ABCD with diagonals meeting at E.',prove='AC ⊥ BD',
 steps=[('AB = BC','Definition of rhombus (all sides equal)'),('AE = EC','Diagonals of a parallelogram bisect each other'),('BE = BE','Reflexive property'),('△ABE ≅ △CBE','SSS'),('∠AEB ≅ ∠CEB','CPCTC'),('∠AEB and ∠CEB are a linear pair','They lie on the straight line AC'),('∠AEB = 90°','Congruent angles that form a linear pair are right angles'),('AC ⊥ BD','Definition of perpendicular lines')],
 idea='Equal sides give congruent triangles; congruent angles on a straight line must be 90°.',
 deep='A rhombus is a parallelogram, which is why the diagonals bisect each other. The same congruence also shows each diagonal bisects the angles at its ends.',
 trap='A rectangle has bisecting diagonals too, but they are not perpendicular. Perpendicularity comes from the equal sides.'),
dict(id='p-rectd',t='quad',title='The diagonals of a rectangle are congruent',
 given='Rectangle ABCD with diagonals AC and BD.',prove='AC = BD',
 steps=[('AB = DC','Opposite sides of a parallelogram are congruent'),('∠ABC and ∠DCB are right angles','Definition of rectangle'),('∠ABC ≅ ∠DCB','All right angles are congruent'),('BC = CB','Reflexive property'),('△ABC ≅ △DCB','SAS'),('AC = DB','CPCTC')],
 idea='Find two triangles that contain the diagonals as corresponding sides.',
 deep='The triangles are △ABC and △DCB: they share BC, have equal legs AB and DC, and equal included right angles. The converse is also true: a parallelogram with congruent diagonals is a rectangle.',
 trap='Check that the angle is between the two sides you use. Here the right angle at B is between AB and BC, so SAS applies.'),
dict(id='p-opp',t='quad',title='If both pairs of opposite sides are equal, the quadrilateral is a parallelogram',
 given='Quadrilateral ABCD with AB = CD and AD = BC.',prove='ABCD is a parallelogram',
 steps=[('Draw diagonal AC','Two points determine a line'),('AC = AC','Reflexive property'),('△ABC ≅ △CDA','SSS'),('∠BAC ≅ ∠DCA','CPCTC'),('AB ∥ CD','If alternate interior angles are congruent, the lines are parallel'),('∠BCA ≅ ∠DAC','CPCTC'),('BC ∥ AD','If alternate interior angles are congruent, the lines are parallel'),('ABCD is a parallelogram','Definition of parallelogram')],
 idea='A diagonal splits the figure into congruent triangles, and congruent triangles give you parallel-line angle pairs.',
 deep='This is the converse of the theorem you proved earlier (opposite sides of a parallelogram are congruent). Together they show the two properties are equivalent.',
 trap='The order of letters matters in △ABC ≅ △CDA: A matches C and B matches D.'),
dict(id='p-split',t='sim',title='A line parallel to one side of a triangle divides the other two sides proportionally',
 given='△ABC with D on AB and E on AC, and DE ∥ BC.',prove='AD/DB = AE/EC',
 steps=[('∠ADE ≅ ∠ABC','Corresponding angles with DE ∥ BC'),('∠A ≅ ∠A','Reflexive property'),('△ADE ∼ △ABC','AA similarity'),('AD/AB = AE/AC','Corresponding sides of similar triangles are proportional'),('AB = AD + DB and AC = AE + EC','Segment addition postulate'),('AD/(AD + DB) = AE/(AE + EC)','Substitution'),('AD·EC = AE·DB','Cross products and simplifying'),('AD/DB = AE/EC','Divide both sides by DB·EC')],
 idea='Parallel lines give equal angles, equal angles give similar triangles, and similar triangles give proportions.',
 deep='The result is the Side-Splitter Theorem. Its converse (equal ratios imply parallel) is also true and is proved with similar triangles and the corresponding angles test.',
 trap='The proportion AD/AB = AE/AC compares part to whole. To get part to part you need the substitution step.'),
dict(id='p-geom',t='rt',title='Altitude to the hypotenuse: h² = xy',
 given='Right △ABC with right angle at C. CD ⊥ AB at D, AD = x, DB = y, CD = h.',prove='h² = xy',
 steps=[('∠ADC and ∠CDB are right angles','Definition of altitude'),('∠ACD + ∠A = 90°','The acute angles of a right triangle are complementary'),('∠A + ∠B = 90°','The acute angles of a right triangle are complementary'),('∠ACD ≅ ∠B','Complements of the same angle are congruent'),('△ADC ∼ △CDB','AA similarity'),('x/h = h/y','Corresponding sides of similar triangles are proportional'),('h² = xy','Cross multiplication')],
 idea='The altitude cuts the big right triangle into two smaller ones that are similar to each other.',
 deep='The same figure gives the other two geometric means: AC² = x·AB and BC² = y·AB. Adding them gives the Pythagorean theorem a second proof.',
 trap='Match vertices in the right order when writing △ADC ∼ △CDB, or the proportion will flip.'),
dict(id='p-cpyth',t='rt',title='Converse of the Pythagorean theorem (Honors)',
 given='△ABC with side lengths a, b, c and a² + b² = c².',prove='∠C is a right angle',
 steps=[('Build right △DEF with legs a and b and hypotenuse x','Construction'),('x² = a² + b²','Pythagorean theorem'),('x² = c²','Substitution (both equal a² + b²)'),('x = c','Take the positive square root (lengths are positive)'),('△ABC ≅ △DEF','SSS'),('∠C ≅ ∠F, so ∠C is a right angle','CPCTC')],
 idea='You cannot assume the triangle is right. Build a right triangle you know, show it has the same sides, and use SSS.',
 deep='This is why the 3-4-5 rope trick works for builders. It also gives the test for acute and obtuse triangles: if a² + b² > c² the triangle is acute; if less, obtuse.',
 trap='Do not start by writing “a² + b² = c² because it is a right triangle”. That assumes what you must prove.'),
dict(id='p-chord',t='cir',title='A radius perpendicular to a chord bisects the chord',
 given='Circle with center O. Radius OM ⊥ chord AB at P.',prove='AP = PB',
 steps=[('Draw OA and OB','Two points determine a line'),('OA = OB','All radii of a circle are congruent'),('OP = OP','Reflexive property'),('∠OPA and ∠OPB are right angles','Definition of perpendicular lines'),('△OPA ≅ △OPB','HL (hypotenuse-leg)'),('AP = PB','CPCTC')],
 idea='Draw the radii to the chord’s endpoints to make two right triangles with equal hypotenuses.',
 deep='The converse also holds: the line from the center to the midpoint of a chord is perpendicular to it. Together they explain why the perpendicular bisector of any chord passes through the center.',
 trap='HL needs a right angle, a hypotenuse and one leg. OA and OB are the hypotenuses, OP is the shared leg.'),
dict(id='p-tseg',t='cir',title='Tangent segments from an outside point are congruent',
 given='P is outside circle O. PA and PB are tangent to the circle at A and B.',prove='PA = PB',
 steps=[('Draw OA, OB and OP','Two points determine a line'),('OA ⊥ PA and OB ⊥ PB','A tangent is perpendicular to the radius at the point of tangency'),('∠OAP and ∠OBP are right angles','Definition of perpendicular lines'),('OA = OB','All radii of a circle are congruent'),('OP = OP','Reflexive property'),('△OAP ≅ △OBP','HL (hypotenuse-leg)'),('PA = PB','CPCTC')],
 idea='Two radii to the tangent points make two right triangles that share the hypotenuse OP.',
 deep='This is why a circle inscribed in a triangle has equal tangent lengths from each vertex, the basis of many Honors perimeter problems.',
 trap='The right angles come from the theorem about tangents and radii, so that theorem must be cited as a reason first.'),
dict(id='p-cyc',t='cir',title='Opposite angles of an inscribed quadrilateral are supplementary',
 given='Quadrilateral ABCD is inscribed in a circle.',prove='m∠A + m∠C = 180°',
 steps=[('m∠A = ½·m(arc BCD)','An inscribed angle is half its intercepted arc'),('m∠C = ½·m(arc BAD)','An inscribed angle is half its intercepted arc'),('m(arc BCD) + m(arc BAD) = 360°','The arcs of a full circle add to 360°'),('m∠A + m∠C = ½·(arc BCD + arc BAD)','Addition and distributive property'),('m∠A + m∠C = ½·360° = 180°','Substitution')],
 idea='Each angle uses the arc on the far side from it; those two arcs together fill the circle.',
 deep='The converse gives a test: a quadrilateral whose opposite angles are supplementary can be inscribed in a circle (cyclic).',
 trap='Use the arc that is opposite the angle (the one it sees), not the arc between the angle’s sides on the near side.'),
dict(id='p-extsum',t='tri',title='An exterior angle equals the sum of the two remote interior angles',
 given='△ABC with D on the extension of BC beyond C.',prove='m∠ACD = m∠A + m∠B',
 steps=[('m∠A + m∠B + m∠ACB = 180°','Triangle angle sum theorem'),('m∠ACB + m∠ACD = 180°','Linear pair postulate'),('m∠A + m∠B + m∠ACB = m∠ACB + m∠ACD','Substitution'),('m∠A + m∠B = m∠ACD','Subtraction property of equality')],
 idea='Both sums equal 180°, so set them equal and cancel the shared angle.',
 deep='This theorem is the engine behind the Exterior Angle Inequality and many angle-chasing problems on contests.',
 trap='The “remote” angles are the two interior angles that are NOT adjacent to the exterior angle.'),
dict(id='p-cpar',t='crd',title='Coordinate proof: diagonals of a parallelogram bisect each other',
 given='Parallelogram with vertices O(0, 0), A(a, 0), B(a + b, c), C(b, c).',prove='The diagonals OB and AC bisect each other',
 steps=[('Place the parallelogram with O at the origin and OA on the x-axis','Choose a convenient coordinate system'),('Midpoint of OB = ((a + b)/2, c/2)','Midpoint formula'),('Midpoint of AC = ((a + b)/2, c/2)','Midpoint formula'),('The two midpoints are the same point','Both equal ((a + b)/2, c/2)'),('The diagonals bisect each other','Each diagonal passes through the midpoint of the other')],
 idea='Choose coordinates that make the algebra easy, then compute with formulas instead of drawing triangles.',
 deep='Coordinate proofs use variables for general shapes: a, b, c stand for any parallelogram, so one calculation covers all of them. Placing a vertex at (0, 0) and a side on the x-axis is the standard first move.',
 trap='Using specific numbers like (3, 4) would only prove the statement for one parallelogram. Use variables.'),
dict(id='p-cmid',t='crd',title='Coordinate proof: the midsegment is parallel to the third side and half as long',
 given='△ABC with A(0, 0), B(2a, 0), C(2b, 2c). M is the midpoint of AC and N is the midpoint of BC.',prove='MN ∥ AB and MN = ½·AB',
 steps=[('M = (b, c) and N = (a + b, c)','Midpoint formula'),('Slope of MN = (c − c)/((a + b) − b) = 0','Slope formula'),('Slope of AB = 0','AB lies on the x-axis'),('MN ∥ AB','Lines with equal slopes are parallel'),('MN = a and AB = 2a','Distance formula'),('MN = ½·AB','Substitution')],
 idea='Doubling the coordinates (2a, 2b, 2c) removes fractions from the midpoints.',
 deep='Compare with the synthetic proof via similar triangles. Coordinates trade clever drawing for mechanical computation, which is often easier on a test.',
 trap='If you pick B = (a, 0) you get fractions everywhere. Choose coordinates so midpoints come out clean.'),
dict(id='p-twoln',t='log',title='Two distinct lines intersect in at most one point (indirect proof)',
 given='ℓ and m are distinct lines.',prove='ℓ and m intersect in at most one point',
 steps=[('Assume ℓ and m intersect in two different points P and Q','Assume the opposite (indirect proof)'),('P and Q are on both lines','Definition of intersection'),('Exactly one line passes through P and Q','Two points determine a line'),('ℓ and m are the same line','Both pass through P and Q'),('This contradicts the given fact that ℓ and m are distinct','Contradiction'),('ℓ and m intersect in at most one point','The assumption was false')],
 idea='In an indirect proof, assume the opposite and chase it until it contradicts something you know.',
 deep='The three parts of any indirect proof: assume the negation, derive a contradiction with a given or a known fact, conclude the original statement.',
 trap='The negation of “at most one” is “at least two”, not “exactly two”. Here “two points” is enough to find the contradiction.'),
dict(id='p-primes',t='log',title='There are infinitely many primes (Euclid, Honors)',
 given='A prime is a whole number greater than 1 whose only positive divisors are 1 and itself.',prove='The list of primes never ends',
 steps=[('Assume there are only finitely many primes p₁, p₂, …, pₙ','Assume the opposite (indirect proof)'),('Let N = p₁·p₂·…·pₙ + 1','Construct a new number'),('N has a prime factor q','Every whole number greater than 1 has a prime factor'),('q is one of p₁, …, pₙ','Our list contains every prime'),('q divides p₁·p₂·…·pₙ and q divides N, so q divides 1','If q divides two numbers it divides their difference'),('No prime divides 1','A prime is greater than 1 (contradiction)'),('There are infinitely many primes','The assumption was false')],
 idea='Multiply all the primes together and add 1. The new number cannot be divisible by any prime on the list.',
 deep='This is one of the oldest indirect proofs (about 300 BCE). It does not claim N is prime; it only shows N has a prime factor outside the list.',
 trap='N = (product) + 1 is not always prime. For example 2·3·5·7·11·13 + 1 = 30031 = 59·509.'),
dict(id='p-npoly',t='par',title='The interior angles of an n-gon add to (n − 2)·180° (Honors)',
 given='A convex polygon with n sides.',prove='Sum of interior angles = (n − 2)·180°',
 steps=[('Pick one vertex and draw all diagonals from it','Construction'),('The polygon is divided into n − 2 triangles','Counting: the two sides touching the vertex are not used'),('The angles of each triangle add to 180°','Triangle angle sum theorem'),('The triangles’ angles together make up the polygon’s interior angles','Angle addition postulate'),('Sum = (n − 2)·180°','Multiplication of n − 2 triangles by 180°')],
 idea='Cut the polygon into triangles from one vertex and count them.',
 deep='Check small cases: a quadrilateral (n = 4) gives 360°, a pentagon 540°. For a regular n-gon each angle is (n − 2)·180°/n. The exterior angles always add to 360°.',
 trap='Draw diagonals from ONE vertex only. Drawing from several vertices makes triangles that overlap.'),
dict(id='p-medalt',t='tri',title='The median to the base of an isosceles triangle is also an altitude',
 given='△ABC with AB = AC. D is the midpoint of BC.',prove='AD ⊥ BC',
 steps=[('BD = DC','Definition of midpoint'),('AB = AC','Given'),('AD = AD','Reflexive property'),('△ABD ≅ △ACD','SSS'),('∠ADB ≅ ∠ADC','CPCTC'),('∠ADB and ∠ADC form a linear pair','They lie along line BC'),('∠ADB = 90°','Congruent angles that form a linear pair are right angles'),('AD ⊥ BC','Definition of perpendicular lines')],
 idea='SSS gives congruent triangles; CPCTC gives equal angles at D; a linear pair of equal angles is two right angles.',
 deep='The same figure shows AD also bisects ∠A. In an isosceles triangle the median, altitude, angle bisector and perpendicular bisector from the apex all coincide.',
 trap='In an equilateral triangle this happens from all three vertices. In a scalene triangle none of these lines coincide.'),
]
